/** Shape of lib/artic/tour-index.ts, generated by scripts/build-tours.mjs. */
export interface TourStopEntry {
  /** mobile-sounds id of the recording. */
  sound: number;
  /** The artwork discussed, when the stop is about one. */
  artwork: number | null;
  title: string | null;
  /** The number visitors key in at the museum. */
  code: string | null;
}

export interface TourEntry {
  id: number;
  minutes: number | null;
  /** mobile-sounds id of the tour's introduction. */
  intro: number | null;
  zhTitle: string | null;
  zhDescription: string | null;
  stops: TourStopEntry[];
}

export interface TourIndex {
  tours: TourEntry[];
  /** Recordings that also exist in Mandarin, by mobile-sounds id. */
  sounds: Record<string, { zhTitle: string | null; zhSrc: string }>;
  /** Recordings about each artwork, by artwork id. */
  commentary: Record<
    string,
    { sound: number; code: string | null; title: string | null }[]
  >;
}
